diff --git a/scripts/bench/fixtures.mjs b/scripts/bench/fixtures.mjs
new file mode 100644
index 0000000..24d62a4
--- /dev/null
+++ b/scripts/bench/fixtures.mjs
@@ -0,0 +1,133 @@
+// Builds realistic test payloads for the CPU benchmark from the recorded samples in docs/samples.
+// Nothing here talks to the network.
+
+import { readFileSync } from 'node:fs';
+import { fileURLToPath } from 'node:url';
+import path from 'node:path';
+
+const here = path.dirname(fileURLToPath(import.meta.url));
+const samplesDir = path.join(here, '..', '..', 'docs', 'samples');
+
+// Small deterministic random generator so every run produces identical data.
+export function makeRandom(seed) {
+  let state = seed >>> 0;
+  return function random() {
+    state = (state * 1664525 + 1013904223) >>> 0;
+    return state / 4294967296;
+  };
+}
+
+// Reads a Yahoo chart sample and returns its 1-minute bars that had trades
+// (Alpaca only returns bars with trades, so zero-volume and null bars are dropped).
+function readTradeBars(fileName) {
+  const json = JSON.parse(readFileSync(path.join(samplesDir, fileName), 'utf8'));
+  const result = json.chart.result[0];
+  const quote = result.indicators.quote[0];
+  const bars = [];
+  result.timestamp.forEach((time, i) => {
+    if (quote.close[i] == null || !quote.volume[i]) return;
+    bars.push({
+      time,
+      open: quote.open[i],
+      high: quote.high[i],
+      low: quote.low[i],
+      close: quote.close[i],
+      volume: quote.volume[i],
+    });
+  });
+  return bars;
+}
+
+// Aggregates 1-minute bars into N-minute bars (bucketed on epoch time).
+function aggregate(bars, minutes) {
+  const bucketSeconds = minutes * 60;
+  const out = [];
+  let current = null;
+  for (const bar of bars) {
+    const bucket = Math.floor(bar.time / bucketSeconds) * bucketSeconds;
+    if (!current || current.time !== bucket) {
+      current = { ...bar, time: bucket };
+      out.push(current);
+    } else {
+      current.high = Math.max(current.high, bar.high);
+      current.low = Math.min(current.low, bar.low);
+      current.close = bar.close;
+      current.volume += bar.volume;
+    }
+  }
+  return out;
+}
+
+// Returns the Alpaca-shaped JSON text for `symbolCount` symbols with `barsPerSymbol` 3-minute bars each:
+//   {"bars":{"SYM":[{"c":..,"h":..,"l":..,"n":..,"o":..,"t":"2026-10-21T23:57:00Z","v":..,"vw":..}, ...]},"next_page_token":null}
+export function buildAlpacaPayload(symbolCount, barsPerSymbol = 640) {
+  const random = makeRandom(42);
+  const templates = ['yahoo_AAPL_1m_5d.json', 'yahoo_QS_1m_5d.json'].map((file) =>
+    aggregate(readTradeBars(file), 3).slice(-barsPerSymbol),
+  );
+  const bars = {};
+  for (let s = 0; s < symbolCount; s++) {
+    const template = templates[s % templates.length];
+    const scale = 0.5 + random() * 3;
+    const symbol = 'T' + String(s).padStart(3, '0');
+    bars[symbol] = template.map((bar) => ({
+      c: +(bar.close * scale).toFixed(4),
+      h: +(bar.high * scale).toFixed(4),
+      l: +(bar.low * scale).toFixed(4),
+      n: 1 + Math.floor(random() * 200),
+      o: +(bar.open * scale).toFixed(4),
+      t: new Date(bar.time * 1000).toISOString().replace('.000Z', 'Z'),
+      v: bar.volume,
+      vw: +(bar.close * scale).toFixed(4),
+    }));
+  }
+  return JSON.stringify({ bars, next_page_token: null });
+}
+
+// ---- Daily snapshot ------------------------------------------------------------------------
+
+export const SNAPSHOT_ROWS = 5600;
+// 70 numeric columns x 4 bytes x 5,600 rows = 1.57 MB, matching the 1.6 MB estimate in the plan.
+export const SNAPSHOT_COLUMNS = [
+  'price', 'change', 'volume', 'avgVol', 'marketCap', 'relVol', 'sma20', 'sma50', 'sma200', 'rsi',
+  'perfWeek', 'perfMonth', 'perfQuarter', 'perfHalf', 'perfYear', 'perfYtd', 'high52', 'low52',
+  'atr', 'beta', 'gap', 'open', 'high', 'low', 'prevClose', 'ahClose', 'ahChange', 'ahVolume',
+  'pe', 'fwdPe', 'peg', 'ps', 'pb', 'pc', 'pfcf', 'epsTtm', 'epsGrowth', 'salesGrowth', 'divYield',
+  'roa', 'roe', 'roi', 'currentRatio', 'quickRatio', 'debtEq', 'grossMargin', 'opMargin',
+  'netMargin', 'payout', 'shortFloat', 'shortRatio', 'floatShares', 'sharesOut', 'insiderOwn',
+  'instOwn', 'volatilityW', 'volatilityM', 'recomm', 'targetPrice', 'avgVol20', 'dollarVol',
+  'sma20Dist', 'sma50Dist', 'sma200Dist', 'high52Dist', 'low52Dist', 'ema20', 'ema50', 'bbUpper',
+  'bbLower', 'macd',
+];
+
+// Columnar snapshot as one ArrayBuffer of float32 columns, plus text columns kept as JSON.
+// Returns { buffer, header } where header = { rows, columns: [{name, offset}], tickers: [...], sectors: [...] }.
+export function buildSnapshot() {
+  const random = makeRandom(7);
+  const rows = SNAPSHOT_ROWS;
+  const buffer = new ArrayBuffer(SNAPSHOT_COLUMNS.length * rows * 4);
+  const columns = SNAPSHOT_COLUMNS.map((name, index) => {
+    const offset = index * rows * 4;
+    const view = new Float32Array(buffer, offset, rows);
+    for (let i = 0; i < rows; i++) {
+      view[i] = name === 'price' ? 0.2 + random() * random() * 400
+        : name === 'change' ? (random() - 0.5) * 20
+        : name === 'avgVol' ? Math.floor(random() * random() * 5e6)
+        : random() * 100;
+    }
+    return { name, offset };
+  });
+  const tickers = Array.from({ length: rows }, (_, i) => 'S' + i.toString(36).toUpperCase().padStart(4, '0'));
+  const sectors = Array.from({ length: rows }, (_, i) => i % 11);
+  return { buffer, header: { rows, columns, tickers, sectors } };
+}
+
+// Same data as a column-oriented JSON text ({"price":[...], ...}) for the "JSON.parse" comparison.
+export function buildSnapshotJson() {
+  const { buffer, header } = buildSnapshot();
+  const obj = { rows: header.rows, tickers: header.tickers, sectors: header.sectors };
+  for (const column of header.columns) {
+    obj[column.name] = Array.from(new Float32Array(buffer, column.offset, header.rows), (x) => +x.toFixed(3));
+  }
+  return JSON.stringify(obj);
+}

diff --git a/scripts/bench/normalize.mjs b/scripts/bench/normalize.mjs
new file mode 100644
index 0000000..5ca2e8b
--- /dev/null
+++ b/scripts/bench/normalize.mjs
@@ -0,0 +1,67 @@
+// The planned /api/bars "normalize" step: Alpaca multi-symbol JSON text -> compact columnar JSON per ticker,
+// plus the header numbers the chart needs. This is the work that must fit into ~10 ms of Function CPU.
+
+const SECONDS_PER_DAY = 86400;
+// Eastern time offset. The real code uses the trading-calendar module; the benchmark assumes EDT (UTC-4)
+// because the cost of the lookup is not what we are measuring.
+const EASTERN_OFFSET_SECONDS = -4 * 3600;
+const REGULAR_CLOSE_SECONDS_OF_DAY = 16 * 3600;
+
+function round4(x) {
+  return Math.round(x * 10000) / 10000;
+}
+
+export function normalizeAlpaca(jsonText) {
+  const parsed = JSON.parse(jsonText);
+  const out = {};
+  for (const symbol of Object.keys(parsed.bars)) {
+    const bars = parsed.bars[symbol];
+    const n = bars.length;
+    const t = new Array(n);
+    const o = new Array(n);
+    const h = new Array(n);
+    const l = new Array(n);
+    const c = new Array(n);
+    const v = new Array(n);
+
+    let lastSessionDay = -1;
+    let sessionVolume = 0;
+    let regularClose = null;
+    for (let i = 0; i < n; i++) {
+      const bar = bars[i];
+      const seconds = Date.parse(bar.t) / 1000;
+      t[i] = seconds;
+      o[i] = round4(bar.o);
+      h[i] = round4(bar.h);
+      l[i] = round4(bar.l);
+      c[i] = round4(bar.c);
+      v[i] = bar.v;
+
+      const local = seconds + EASTERN_OFFSET_SECONDS;
+      const day = Math.floor(local / SECONDS_PER_DAY);
+      if (day !== lastSessionDay) {
+        lastSessionDay = day;
+        sessionVolume = 0;
+        regularClose = null;
+      }
+      sessionVolume += bar.v;
+      if (local - day * SECONDS_PER_DAY < REGULAR_CLOSE_SECONDS_OF_DAY) regularClose = c[i];
+    }
+
+    out[symbol] = {
+      t, o, h, l, c, v,
+      last: n ? t[n - 1] : null,
+      sessionVolume,
+      regularClose,
+    };
+  }
+  return out;
+}
+
+// What the Function actually returns / caches: one JSON string per ticker, then one combined body.
+export function serialize(normalized) {
+  const perTicker = {};
+  for (const symbol of Object.keys(normalized)) perTicker[symbol] = JSON.stringify(normalized[symbol]);
+  const body = '{' + Object.keys(perTicker).map((s) => JSON.stringify(s) + ':' + perTicker[s]).join(',') + '}';
+  return { perTicker, body };
+}

diff --git a/scripts/bench/run.mjs b/scripts/bench/run.mjs
new file mode 100644
index 0000000..c3c0483
--- /dev/null
+++ b/scripts/bench/run.mjs
@@ -0,0 +1,62 @@
+// CPU benchmark for the two hot Function paths. Run: node scripts/bench/run.mjs [iterations]
+// Prints median / p95 / max milliseconds per request and the first (cold) iteration, as JSON on the last line.
+
+import { buildAlpacaPayload, buildSnapshot, buildSnapshotJson, SNAPSHOT_ROWS } from './fixtures.mjs';
+import { normalizeAlpaca, serialize } from './normalize.mjs';
+import { screenBinary, screenJson } from './screener.mjs';
+
+const iterations = Number(process.argv[2]) || 500;
+
+function percentile(sortedValues, p) {
+  return sortedValues[Math.min(sortedValues.length - 1, Math.floor(sortedValues.length * p))];
+}
+
+function measure(label, work) {
+  const times = [];
+  let first = null;
+  for (let i = 0; i < iterations; i++) {
+    const started = process.hrtime.bigint();
+    work();
+    const elapsedMs = Number(process.hrtime.bigint() - started) / 1e6;
+    if (i === 0) first = elapsedMs;
+    times.push(elapsedMs);
+  }
+  const sorted = [...times].sort((a, b) => a - b);
+  const result = {
+    label,
+    firstMs: +first.toFixed(2),
+    medianMs: +percentile(sorted, 0.5).toFixed(2),
+    p95Ms: +percentile(sorted, 0.95).toFixed(2),
+    maxMs: +sorted.at(-1).toFixed(2),
+  };
+  console.log(
+    `${label.padEnd(52)} first ${String(result.firstMs).padStart(7)}  median ${String(result.medianMs).padStart(6)}  p95 ${String(result.p95Ms).padStart(6)}  max ${String(result.maxMs).padStart(6)} ms`,
+  );
+  return result;
+}
+
+const results = [];
+
+// --- /api/bars normalize -------------------------------------------------------------------
+// [symbols per call, bars per symbol]. 640 bars is the pessimistic size from the plan (5,120 bars for 8 symbols);
+// 350 bars is the real need: ~150 visible + 200 warm-up for SMA 200.
+const barCases = [[4, 640], [8, 640], [4, 350], [8, 350], [44, 640]];
+for (const [symbolCount, barsPerSymbol] of barCases) {
+  const text = buildAlpacaPayload(symbolCount, barsPerSymbol);
+  const barCount = symbolCount * barsPerSymbol;
+  const tag = `${symbolCount}x${barsPerSymbol}`;
+  console.log(`\npayload: ${symbolCount} symbols x ${barsPerSymbol} bars = ${barCount} bars, ${(text.length / 1024).toFixed(0)} KB JSON`);
+  results.push({ ...measure(`bars parse only (${tag})`, () => JSON.parse(text)), kb: Math.round(text.length / 1024) });
+  results.push(measure(`bars parse + normalize (${tag})`, () => normalizeAlpaca(text)));
+  results.push(measure(`bars parse + normalize + stringify (${tag})`, () => serialize(normalizeAlpaca(text))));
+}
+
+// --- /api/screener ---------------------------------------------------------------------------
+const { buffer, header } = buildSnapshot();
+const headerText = JSON.stringify(header);
+const jsonText = buildSnapshotJson();
+console.log(`\nsnapshot: ${SNAPSHOT_ROWS} rows, binary ${(buffer.byteLength / 1048576).toFixed(2)} MB (+ ${(headerText.length / 1024).toFixed(0)} KB header), JSON ${(jsonText.length / 1048576).toFixed(2)} MB`);
+results.push(measure('screener binary (typed-array views, header parse)', () => screenBinary(buffer, headerText)));
+results.push(measure('screener JSON.parse of the whole snapshot', () => screenJson(jsonText)));
+
+console.log('\n' + JSON.stringify(results));

diff --git a/scripts/bench/screener.mjs b/scripts/bench/screener.mjs
new file mode 100644
index 0000000..f900941
--- /dev/null
+++ b/scripts/bench/screener.mjs
@@ -0,0 +1,42 @@
+// The planned /api/screener step: filter + sort the nightly snapshot and return one page of rows.
+// Two input formats are measured:
+//   binary: a JSON header (tickers, column offsets) followed by float32 columns read through typed-array views
+//   json:   one column-oriented JSON text that must be JSON.parse'd on every cold start
+
+// Query used for the benchmark: the reference scenario (price over $1, average volume over 50K),
+// sorted by after-hours change, top 120 rows.
+export const QUERY = { minPrice: 1, minAvgVol: 50000, sortBy: 'ahChange', descending: true, limit: 120 };
+const OUTPUT_COLUMNS = ['price', 'change', 'ahChange', 'volume', 'avgVol', 'marketCap', 'relVol', 'rsi', 'sma20', 'sma50', 'sma200', 'perfWeek'];
+
+function pickPage(columnOf, tickers, query) {
+  const price = columnOf('price');
+  const avgVol = columnOf('avgVol');
+  const sortColumn = columnOf(query.sortBy);
+
+  const matches = [];
+  for (let i = 0; i < price.length; i++) {
+    if (price[i] > query.minPrice && avgVol[i] > query.minAvgVol) matches.push(i);
+  }
+  const sign = query.descending ? -1 : 1;
+  matches.sort((a, b) => sign * (sortColumn[a] - sortColumn[b]));
+  const page = matches.slice(0, query.limit);
+
+  const columns = OUTPUT_COLUMNS.map((name) => {
+    const values = columnOf(name);
+    return page.map((i) => values[i]);
+  });
+  return JSON.stringify({ total: matches.length, tickers: page.map((i) => tickers[i]), cols: OUTPUT_COLUMNS, columns });
+}
+
+// buffer: ArrayBuffer of float32 columns. header: { rows, columns: [{name, offset}], tickers }.
+export function screenBinary(buffer, headerText, query = QUERY) {
+  const header = JSON.parse(headerText);
+  const offsets = new Map(header.columns.map((column) => [column.name, column.offset]));
+  const columnOf = (name) => new Float32Array(buffer, offsets.get(name), header.rows);
+  return pickPage(columnOf, header.tickers, query);
+}
+
+export function screenJson(jsonText, query = QUERY) {
+  const data = JSON.parse(jsonText);
+  return pickPage((name) => data[name], data.tickers, query);
+}

diff --git a/scripts/bench/alpaca_bench.mjs b/scripts/bench/alpaca_bench.mjs
new file mode 100644
index 0000000..ac42773
--- /dev/null
+++ b/scripts/bench/alpaca_bench.mjs
@@ -0,0 +1,21 @@
+// CPU bench: parse + normalize + stringify an Alpaca multi-symbol bars payload.
+import fs from "node:fs";
+const raw = fs.readFileSync(process.argv[2], "utf8");
+function run() {
+  const j = JSON.parse(raw);
+  const out = {};
+  for (const [sym, bars] of Object.entries(j.bars)) {
+    out[sym] = {
+      t: bars.map(b => Math.floor(Date.parse(b.t) / 1000)),
+      o: bars.map(b => b.o), h: bars.map(b => b.h),
+      l: bars.map(b => b.l), c: bars.map(b => b.c), v: bars.map(b => b.v),
+    };
+  }
+  return JSON.stringify(out).length;
+}
+for (let i = 0; i < 20; i++) run();
+const times = [];
+let size = 0;
+for (let i = 0; i < 200; i++) { const s = performance.now(); size = run(); times.push(performance.now() - s); }
+times.sort((a, b) => a - b);
+console.log(`payload ${raw.length} B -> ${size} B; median ${times[100].toFixed(2)} ms, p95 ${times[190].toFixed(2)} ms`);

